// ── Validate secret header ─────────────────────────────────────────────────
const secret = $input.first().headers['x-webhook-secret'];
if (secret !== $env.WEBHOOK_SECRET) {
  throw new Error('Unauthorized: Invalid webhook secret');
}

// ── Extract the Supabase DB Webhook payload ─────────────────────────────────
// Supabase sends: { type: 'INSERT', table: 'employee_requests', record: {...} }
const body = $input.first().body;
const record = body.record ?? body;

if (!record.id || !record.request_type) {
  throw new Error('Invalid payload: missing required fields');
}

// ── Build the structured user prompt for Gemini ─────────────────────────────
const userPrompt = `Evaluate the following employee request:
- Request Type: ${record.request_type}
- Start Date: ${record.start_date}
- End Date: ${record.end_date}
- Urgency: ${record.urgency}
- Justification: ${record.justification}`;

return [{
  json: {
    requestId:    record.id,
    userId:       record.user_id,
    requestType:  record.request_type,
    startDate:    record.start_date,
    endDate:      record.end_date,
    urgency:      record.urgency,
    justification: record.justification,
    userPrompt,
  }
}];

