// Parse Gemini response into the AI evaluation JSON
const geminiResponse = $input.first().json;
const candidate = geminiResponse.candidates?.[0];
if (!candidate) throw new Error('Gemini returned no candidates');

let aiEval;
try {
  const rawText = candidate.content?.parts?.[0]?.text ?? '{}';
  aiEval = JSON.parse(rawText);
} catch (e) {
  throw new Error('Failed to parse Gemini JSON response: ' + e.message);
}

// Validate required fields
const required = ['decision', 'reasoning', 'calendarEventRequired', 'sentimentAnalysis'];
for (const field of required) {
  if (aiEval[field] === undefined) {
    throw new Error(`Missing field in AI response: ${field}`);
  }
}

// Map Gemini decision → Supabase status
const statusMap = {
  'Approved':              'Approved',
  'Requires Manual Review': 'Requires Manual Review',
};
const supabaseStatus = statusMap[aiEval.decision] ?? 'Requires Manual Review';

return [{
  json: {
    ...($node['Validate & Extract Payload'].json),
    aiEvaluation: aiEval,
    supabaseStatus,
  }
}];

